from rich.text import Text

def failing_generator():
    yield ("hello", None)
    raise Exception("boom")
    yield ("world", None)

def test_append_tokens_exception():
    t = Text()
    try:
        t.append_tokens(failing_generator())
    except Exception:
        pass

    print(f"len(t): {len(t)}")
    print(f"t.plain: {t.plain}")
    assert len(t) == len(t.plain)

if __name__ == "__main__":
    test_append_tokens_exception()

